UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Coral reefs cover less than one percent of the ocean floor yet support roughly a quarter of all marine species. This disparity is explained by the structure reefs provide: a three-dimensional habitat with countless niches. When water temperatures rise beyond a narrow tolerance range, corals expel the symbiotic algae that supply most of their energy, a process known as bleaching. Bleached corals are not dead, and they can recover if conditions normalize quickly enough. Prolonged warm periods, however, shift the balance from recovery to mortality, and repeated events simplify the reef structure, reducing the number of available niches and the biodiversity they supported.' WHERE e.exam_code = 'TP-PRACTICE-2026-MINI' AND q.order_no = 8;
