UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Psychology lecture. Imagine you must remember fifty words. Would you study the list twice in one sitting, or spread the same amount of study time over four days? Students almost always choose the single session because it feels fluent, yet testing shows the opposite. Information rehearsed after a delay must be rebuilt from memory each time, and that act of rebuilding strengthens the trace, whereas rereading a list you have just seen feels easy but adds almost nothing. The practical advice from decades of spacing studies is blunt: study less at a time and more often, and accept that the harder session is the one that works.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET02' AND q.order_no = 90;
