UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Long before any European government issued paper money, merchants in the Chinese region of Sichuan were already using it. Under the Song dynasty, which began in 960, currency there was heavy iron coin, so awkward to carry that a large purchase needed a cartload of metal. Records describe seventeen notes, each promising the bearer a set number of coins at a named shop, circulating instead of the coins themselves. The court first treated these notes as a convenient local habit, then recognised their value as a source of revenue and, in the early eleventh century, opened state workshops that printed official notes on mulberry bark paper with coloured ink and registered serial numbers. Forgery was punished severely, yet repeated overissue to pay for military spending undermined confidence, and the dynasty revised its note series so often that historians now trace monetary policy through the changing denominations.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET03' AND q.order_no = 39;
