UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Listen to the academic talk. What is the talk mainly about?', q.body_text = 'Professor: Let us finish the discussion of self-organisation with the best-studied example, the ant colony. A colony has no manager. Instead, workers respond to local cues, chiefly how often they bump into nestmates carrying a particular load. If foragers return slowly, encounters are rare, and idle workers stay inside the nest; if they speed up, meetings double, and more ants drift toward the nest entrance to join the trail. Response thresholds differ among individuals, so some workers start a risky job sooner than their siblings, which keeps a reserve of specialists for sudden threats. The same feedback explains how colonies shift from brood care to foraging as they grow: older, larger nests simply hold ants who meet each other more. Notice what the model claims: a stable division of labour can arise from blind local rules with nobody planning it.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET04' AND q.order_no = 90;
