UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'If enough members of a community cannot be infected, a germ that enters the population may fail to find a next host and its chain of transmission breaks. Public-health researchers call this herd immunity, and the share of people who must be protected to bring it about is the threshold. The threshold is not a fixed number: a highly contagious disease such as measles requires roughly ninety-five percent of a population to be immune, whereas polio needs a far smaller share. Vaccination raises the protected share without exposing people to the disease itself, so reaching the threshold shields those who cannot be vaccinated, such as newborns or the severely ill. The weak point is uneven coverage. A community that vaccinates uniformly can hold the line, but a cluster that declines together leaves pockets of susceptibility through which the germ travels, and the protection promised to everyone thins out.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET05' AND q.order_no = 42;
