UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Listen to the talk. What is the talk mainly about?', q.choices_json = '["The origin of poetry on clay tablets","How writing grew out of the need to record rations","The daily diet of temple workers","The trade routes for barley"]', q.body_text = 'Professor: Today we look at why the first writing was almost boring. The oldest clay tablets from southern Mesopotamia are not poems or prayers; they are tallies of grain, beer, and sheep handed out as rations. A worker received a fixed measure of barley each day, and the temple had to record who took it, or the storehouse would be emptied without a trace. So the earliest signs are numbers, a picture of a stalk, and a mark naming the person. Only later did the wedge-shaped strokes become flexible enough to say more than a receipt. The lesson is that a technology we now link with literature and law grew out of a plain accounting need: keeping track of what was owed to whom. That is why, when you read a ration list, you are seeing writing at its first everyday work, pressed into wet clay.', q.explanation = 'The talk explains that the earliest tablets recorded grain and beer rations, so writing grew out of an accounting need.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET05' AND q.order_no = 90;
