UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Until the late twentieth century, motor fuel was laced with tetraethyl lead, a compound added because it silenced engine knock and let engines run at higher, more efficient compression. The cost was invisible. Burning lead-treated fuel released fine particles that settled along roadsides and entered the air people breathed, and once inside the body lead accumulates, damaging the nervous system, with children the most vulnerable. Measuring lead in children''s blood in major cities showed worrying levels, and the figures fell sharply wherever regulators removed lead from petrol. Refineries resisted, warning that unleaded fuel would damage older engines, until catalytic converters, which are poisoned by lead, made unleaded fuel technically necessary rather than merely desirable. Many countries had banned leaded petrol by the year 2000, and the decline in childhood blood-lead levels within a few years is taken as one of the clearest public-health gains from a single regulation.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET06' AND q.order_no = 36;
