UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Pendulum clocks keep better time than any earlier mechanism, but their accuracy hides a subtle problem: metals expand when warm. A steel rod lengthens as the temperature rises, and because a pendulum''s swing slows as it grows longer, a summer clock loses time that a winter clock did not lose. Around 1726 the English clockmaker John Harrison solved this with the gridiron pendulum, an assembly of alternating brass and steel rods joined to one bob. Brass expands more than steel, so the brass rods lift the bob while the steel rods lower it. Adjusted in the right proportions, the two effects cancel, and the distance from the pivot to the bob stays almost fixed as the room warms or cools. The gridiron did not make clocks perfect, but by trading one kind of error for its opposite it let a household timepiece run for weeks without the daily correction that plainer pendulums demanded.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET07' AND q.order_no = 36;
